body:
### Tested versions

Reproducible: 4.4.1stable

### System information

Windows 11 - godot 4.4.1.stable - Vulkan(forward+) - nvidia geforce gtx 1660

### Issue description

https://github.com/user-attachments/assets/3de7009b-7f7d-4df5-9f0c-c8b708a035a3           

There was performance issue between **CharacterBody3D** when both party collided.
I only used generated collision "Simplified Convex" and move_and_slide function that handles collision.
i don't get why i'm experiencing this issue..

![Image](https://github.com/user-attachments/assets/0c0051c2-d64a-464e-abfd-5128cd489813)

### Steps to reproduce

**Player Script Node**

**Enemy Script Node**

```gdscript
extends CharacterBody3D

extends CharacterBody3D

@export var speed = 5.0
@export var jump_velocity = 8.0
@export var mouse_sensitivity = 0.002

var subscribers : int = 0
var crowds : int = 0

var camera_rotation = Vector2.ZERO

@onready var camera = $SpringArm3D/Camera3D

func _ready():
	add_to_group("Player")
	Input.set_mouse_mode(Input.MOUSE_MODE_CAPTURED)

func _input(event):
	if event is InputEventMouseMotion:
		camera_rotation.x -= event.relative.y * mouse_sensitivity
		camera_rotation.y -= event.relative.x * mouse_sensitivity
		camera_rotation.x = clamp(camera_rotation.x, -1.2, 1.2)
		$SpringArm3D.rotation.x = camera_rotation.x
		rotation.y = camera_rotation.y

func _physics_process(delta):
	var input_dir = Vector3.ZERO
	if Input.is_action_pressed("move_forward"):
		input_dir.z -= 1
	if Input.is_action_pressed("move_back"):
		input_dir.z += 1
	if Input.is_action_pressed("move_left"):
		input_dir.x -= 1
	if Input.is_action_pressed("move_right"):
		input_dir.x += 1
	input_dir = input_dir.normalized()
	var direction = (transform.basis * input_dir).normalized()
	velocity.x = direction.x * speed
	velocity.z = direction.z * speed
	if not is_on_floor():
		velocity.y -= 9.8 * delta
	else:
		if (Input.is_action_just_pressed("TakeAction")):
			velocity.y = jump_velocity
			DoSometingInteresting()
	move_and_slide()


@export var speed = 3.0

@onready var target = get_tree().get_nodes_in_group("Player")[0]

func _physics_process(delta):
	var direction = (target.global_transform.origin - global_transform.origin).normalized()
	velocity = direction * speed
	move_and_slide()
```

